/**
 * Runs the innetjs client build with the CSS generated by buildEnv.ts.
 *
 * innetjs exposes every host variable that starts with INNETJS_ENV_PREFIX to
 * the bundle, so the prefix is scoped to this plugin's namespace and other
 * plugins' INNETJS_* values never enter the build.
 */

import { spawnSync } from 'node:child_process'
import { existsSync, readFileSync } from 'node:fs'

import * as dotenv from 'dotenv'

const ENV_PREFIX = 'DSH_PLUGIN_GROQ_SPEECH_'
const CSS_KEY = `${ENV_PREFIX}CSS`
const env = { ...process.env }

env.INNETJS_ENV_PREFIX = ENV_PREFIX

if (existsSync('.env.theme')) {
  const theme = dotenv.parse(readFileSync('.env.theme', 'utf8'))

  if (typeof theme[CSS_KEY] === 'string') env[CSS_KEY] = theme[CSS_KEY]
}

const command = process.platform === 'win32' ? 'innetjs.cmd' : 'innetjs'
const result = spawnSync(
  command,
  ['build', '-i', 'client', '-tc', '-lc', '-e'],
  { env, stdio: 'inherit' },
)

process.exit(result.status === null ? 1 : result.status)
